import type {
  Difficulty,
  MealType,
  Recipe,
  RecipeCategory,
  RecipeIngredient,
  Unit,
} from "@/types";
import { CATALOG_BY_ID } from "./ingredients";
import { SUBSTITUTIONS } from "./substitutions";

/**
 * Recipes are stored in a compact tuple form and expanded once at module load.
 * Everything is bundled with the app — no network access is ever required.
 *
 * Ingredient string format: "ingredient-id:amount:unit" joined by "|".
 * An empty amount means "to taste" / availability only.
 */
type Row = [
  id: string,
  name: string,
  description: string,
  category: RecipeCategory,
  meals: MealType[],
  difficulty: Difficulty,
  time: number,
  servings: number,
  required: string,
  optional: string,
  steps: string,
  tags: string,
];

function titleize(id: string) {
  return id
    .split("-")
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
    .join(" ");
}

function parseIngredients(spec: string, optional: boolean): RecipeIngredient[] {
  if (!spec.trim()) return [];
  return spec.split("|").map((part) => {
    const [id, amount, unit] = part.split(":");
    const catalog = CATALOG_BY_ID[id];
    return {
      ingredientId: id,
      name: catalog?.name ?? titleize(id),
      amount: amount ? Number(amount) : undefined,
      unit: (unit as Unit) || catalog?.defaultUnit || "available",
      optional,
    };
  });
}

