export const RECIPES: Recipe[] = ROWS.map((row) => {
  const [
    id,
    name,
    description,
    category,
    mealType,
    difficulty,
    cookingTime,
    servings,
    required,
    optional,
    steps,
    tags,
  ] = row;
  const ingredients = parseIngredients(required, false);
  const optionalIngredients = parseIngredients(optional, true);
  const substitutions: Record<string, string[]> = {};
  for (const ing of [...ingredients, ...optionalIngredients]) {
    const subs = SUBSTITUTIONS[ing.ingredientId];
    if (subs?.length) substitutions[ing.ingredientId] = subs;
  }
  return {
    id,
    name,
    description,
    category,
    mealType,
    difficulty,
    cookingTime,
    servings,
    ingredients,
    optionalIngredients,
    instructions: steps.split("||").filter(Boolean),
    tags: tags.split("|").filter(Boolean),
    substitutions,
  };
});

export const RECIPE_BY_ID: Record<string, Recipe> = Object.fromEntries(
  RECIPES.map((r) => [r.id, r]),
);

export const DISCOVER_SECTIONS: { title: string; match: (r: Recipe) => boolean }[] = [
  { title: "Popular Everyday Recipes", match: (r) => r.tags.includes("popular") },
  { title: "Quick Meals", match: (r) => r.cookingTime <= 20 },
  { title: "Budget Friendly", match: (r) => r.tags.includes("budget") },
  { title: "15 Minute Meals", match: (r) => r.cookingTime <= 15 },
  { title: "Breakfast Ideas", match: (r) => r.mealType.includes("Breakfast") },
  { title: "Comfort Food", match: (r) => r.tags.includes("comfort food") },
  { title: "Vegetarian", match: (r) => r.tags.includes("vegetarian") },
  { title: "High Protein", match: (r) => r.tags.includes("high protein") },
  { title: "Indonesian Favorites", match: (r) => r.category === "Indonesian" },
  { title: "Asian Favorites", match: (r) => r.category === "Asian" },
];
